        StringPrim.GetProgramArgs.registerProgramArgs(args);

        EvaluatorTask evTask = new EvaluatorTask(fr, p, "run");
        try {
            group.invoke(evTask);
            if (evTask.causedException()) {
                throw evTask.taskException();
            }
            return evTask.result();
        }
        finally {
            // group.interruptAll();
        }
    }


