  static Method m(Class c, String n, Class... ps) throws Exception { Method x = c.getDeclaredMethod(n, ps); x.setAccessible(true); return x; }
  static Object get(Object o, String f) throws Exception { Field x = o.getClass().getDeclaredField(f); x.setAccessible(true); return x.get(o); }
  public static void main(String[] a) throws Throwable {
    Shell.setPhaseOrder(PhaseOrder.interpreterPhaseOrder);
    Shell.setCompiledExprDesugaring(false);
    Shell.setScala(false);
    APIName apiname = NodeFactory.makeAPIName(NodeFactory.testSpan, a[1]);
    GraphRepository repository = Shell.specificInterpreterRepository(ProjectProperties.SOURCE_PATH.prepend(a[0]));
    ComponentIndex ci = repository.getLinkedComponent(apiname);
    try { Driver.runProgram(repository, ci, new ArrayList<String>()); } catch (Throwable t) { String s = t.toString(); System.out.println("run threw: " + s.substring(0, Math.min(300, s.length())).replace('\n',' ')); }
    Field f = Driver.class.getDeclaredField("components"); f.setAccessible(true);
    List<ComponentWrapper> comps = (List<ComponentWrapper>) f.get(null);
    Class cc = Class.forName("com.sun.fortress.interpreter.evaluator.BuildEnvironments$ComprisesCheck");
    Constructor k = cc.getDeclaredConstructor(List.class); k.setAccessible(true);
    Object chk = k.newInstance(comps);
    List decls = (List) get(chk, "declarations");
    Map declared = (Map) get(chk, "declared");
    Method sup = m(cc, "supertypesOf", Class.forName("com.sun.fortress.interpreter.evaluator.BuildEnvironments$ComprisesCheck$Declared"));
    Method lst = m(cc, "listedBy", Class.forName("com.sun.fortress.interpreter.evaluator.BuildEnvironments$ComprisesCheck$Declared"), List.class);
    Method inel = m(cc, "ineligible", Class.forName("com.sun.fortress.interpreter.evaluator.BuildEnvironments$ComprisesCheck$Declared"), List.class);
    int pairs = 0, same = 0;
    for (Object x : decls) {
      for (Object e : (List) sup.invoke(chk, x)) {
        Object head = get(e, "head"); if (head == null) continue;
        Object h = declared.get(head); if (h == null) continue;
        List listed = (List) lst.invoke(chk, h, get(e, "args")); if (listed == null) continue;
        pairs++;
        boolean sameUnit = ((Integer) get(h, "unit")).equals(get(x, "unit"));
        if (sameUnit) same++;
        String why = (String) inel.invoke(chk, x, listed);
        String hn = NodeUtil.getName((TraitObjectDecl) get(h, "decl")).getText();
        String xn = NodeUtil.getName((TraitObjectDecl) get(x, "decl")).getText();
        String xu = comps.get((Integer) get(x, "unit")).getCompilationUnit().getName().toString();
        String hu = comps.get((Integer) get(h, "unit")).getCompilationUnit().getName().toString();
        if (why != null) System.out.println("BREACH " + (sameUnit ? "same " : "cross ") + xu + "." + xn + " extends " + hu + "." + hn + why);
      }
    }
    System.out.println("closed-trait extensions: " + pairs + " (same unit " + same + "), units " + comps.size());
    System.exit(0);
  }
}
